"use server";

import { revalidatePath } from "next/cache";
import { readFile, writeFile } from "fs/promises";
import { join } from "path";

const PREFERENCES_FILE = join(process.cwd(), "preferences.json");

async function getPreferences(): Promise<{ notifications: boolean }> {
  try {
    const data = await readFile(PREFERENCES_FILE, "utf-8");
    return JSON.parse(data);
  } catch {
    return { notifications: false };
  }
}

export async function toggleNotificationPreference(): Promise<void> {
  const preferences = await getPreferences();
  preferences.notifications = !preferences.notifications;
  await writeFile(PREFERENCES_FILE, JSON.stringify(preferences, null, 2));
  revalidatePath("/");
}

export async function getNotificationPreference(): Promise<boolean> {
  const preferences = await getPreferences();
  return preferences.notifications;
}

import { getNotificationPreference, toggleNotificationPreference } from "./actions";

export default async function Home() {
  const notificationsEnabled = await getNotificationPreference();

  return (
    <main>
      <h1>Settings</h1>
      <form action={toggleNotificationPreference}>
        <p>Notifications: {notificationsEnabled ? "On" : "Off"}</p>
        <button type="submit">
          Turn {notificationsEnabled ? "Off" : "On"}
        </button>
      </form>
    </main>
  );
}

